	public static function queue($lecture_id,$action='upsert',$institute_id=0){global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$lecture=EduFlow_Class_Service::get($lecture_id,$institute_id);if(!$lecture){return new WP_Error('lecture_not_found','Lecture not found.');}$table=EduFlow_DB::table('google_events');$key='google:'.$institute_id.':'.$lecture_id;$now=current_time('mysql',true);$wpdb->query($wpdb->prepare("INSERT INTO $table (institute_id,lecture_id,sync_key,sync_status,sync_action,status,created_at,updated_at) VALUES (%d,%d,%s,'pending',%s,'active',%s,%s) ON DUPLICATE KEY UPDATE sync_status='pending',sync_action=VALUES(sync_action),last_error=NULL,updated_at=VALUES(updated_at)",$institute_id,$lecture_id,$key,$action,$now,$now));$job_key=$key.':'.$action.':'.hash('sha256',$lecture['updated_at'].$lecture['class_status']);$job=EduFlow_Job_Service::enqueue('google_calendar_sync',array('institute_id'=>$institute_id,'lecture_id'=>$lecture_id,'action'=>$action),$job_key,$institute_id);if(is_wp_error($job)){EduFlow_Job_Service::retry_failed_by_key($job_key);}return true;}
	public static function sync_job($unused,$payload){return self::sync(absint($payload['lecture_id']??0),sanitize_key($payload['action']??'upsert'),absint($payload['institute_id']??0));}
	public static function sync($lecture_id,$action='upsert',$institute_id=0){if(EduFlow_YTC_Meet_Bridge::connected()){return EduFlow_YTC_Meet_Bridge::sync($lecture_id,$action,$institute_id);}global $wpdb;$institute_id=$institute_id?:EduFlow_Settings::institute_db_id();$lecture=EduFlow_Class_Service::get($lecture_id,$institute_id);if(!$lecture){return new WP_Error('permanent_google_sync','Lecture not found.');}$integration=self::integration($institute_id);$map_table=EduFlow_DB::table('google_events');$map=$wpdb->get_row($wpdb->prepare("SELECT * FROM $map_table WHERE institute_id=%d AND lecture_id=%d",$institute_id,$lecture_id),ARRAY_A);if(!$map){self::queue($lecture_id,$action,$institute_id);$map=$wpdb->get_row($wpdb->prepare("SELECT * FROM $map_table WHERE institute_id=%d AND lecture_id=%d",$institute_id,$lecture_id),ARRAY_A);}if(!$map){return new WP_Error('permanent_google_sync','Google event mapping could not be created.');}$token=self::access_token($institute_id);if(is_wp_error($token)){return self::fail($map,$token,false);}$calendar=$integration['calendar_id']?:'primary';if('cancel'===$action||'cancelled'===$lecture['class_status']){if(!$map['google_event_id']){self::mark($map,'cancelled',null);return true;}$url='https://www.googleapis.com/calendar/v3/calendars/'.rawurlencode($calendar).'/events/'.rawurlencode($map['google_event_id']).'?sendUpdates=all';$response=self::request('DELETE',$url,null,$token,true);if(is_wp_error($response)){return self::fail($map,$response,self::retryable($response));}self::mark($map,'cancelled',null);EduFlow_Audit_Service::log('google_event_cancelled','class',$lecture['canonical_id'],null,array('sync_status'=>'cancelled'),$institute_id);return true;}$body=self::event_body($lecture,$institute_id);$base='https://www.googleapis.com/calendar/v3/calendars/'.rawurlencode($calendar).'/events';if($map['google_event_id']){$result=self::request('PATCH',$base.'/'.rawurlencode($map['google_event_id']).'?conferenceDataVersion=1&sendUpdates=all',$body,$token);$audit='google_event_updated';if(is_wp_error($result)&&'google_http_404'===$result->get_error_code()){$result=self::request('POST',$base.'?conferenceDataVersion=1&sendUpdates=all',$body,$token);$audit='google_event_created';}}else{$result=self::request('POST',$base.'?conferenceDataVersion=1&sendUpdates=all',$body,$token);$audit='google_event_created';}if(is_wp_error($result)){return self::fail($map,$result,self::retryable($result));}$event_id=sanitize_text_field($result['id']??'');$meet=self::meet_url($result);if(!$event_id){return self::fail($map,new WP_Error('google_invalid_response','Google returned no event ID.'),false);}$now=current_time('mysql',true);$conference_status=sanitize_key($result['conferenceData']['createRequest']['status']['statusCode']??'');$sync_status=$meet?'synced':('failure'===$conference_status?'failed':'pending');$mapping_updated=$wpdb->update($map_table,array('google_event_id'=>$event_id,'google_calendar_id'=>$calendar,'google_meet_url'=>$meet?:null,'google_event_url'=>esc_url_raw($result['htmlLink']??''),'sync_status'=>$sync_status,'sync_action'=>'upsert','sync_attempts'=>(int)$map['sync_attempts']+1,'last_synced_at'=>$now,'last_error'=>null,'updated_at'=>$now),array('id'=>$map['id'],'institute_id'=>$institute_id));if(false===$mapping_updated){return self::fail($map,new WP_Error('duplicate_google_event_id','Google Event ID is already mapped to another lecture.'),false);}$wpdb->update(EduFlow_DB::table('classes'),array('meet_url'=>$meet?:null,'external_event_id'=>$event_id,'updated_at'=>$now),array('id'=>$lecture_id,'institute_id'=>$institute_id));if(!$meet){$pending_error=new WP_Error('google_conference_'.($conference_status?:'pending'),'Google Calendar event exists but Meet creation is '.($conference_status?:'pending').'.');return self::fail(array_merge($map,array('sync_attempts'=>(int)$map['sync_attempts']+1)),$pending_error,'failure'!==$conference_status);}update_option('eduflow_google_last_successful_sync',$now,false);EduFlow_Audit_Service::log($audit,'class',$lecture['canonical_id'],null,array('google_sync_status'=>'synced','meet_created'=>(bool)$meet),$institute_id);if($meet){EduFlow_Audit_Service::log('meet_created','class',$lecture['canonical_id'],null,array('meet_available'=>true),$institute_id);EduFlow_Notification_Service::notify_class($lecture_id,'meet_ready','Meet ready','Google Meet is ready for your class.',$event_id,$institute_id);}return true;}
	private static function event_body($lecture,$institute_id){global $wpdb;$batch=EduFlow_Batch_Service::get($lecture['batch_id'],$institute_id);$teacher=EduFlow_Teacher_Service::get($lecture['teacher_id'],$institute_id);$emails=array();if($teacher&&is_email($teacher['email']??'')){$emails[]=strtolower($teacher['email']);}$students=EduFlow_DB::table('students');if('demo'===$lecture['class_type']&&!$lecture['batch_id']){$sessions=EduFlow_DB::table('demo_sessions');$bookings=EduFlow_DB::table('demo_bookings');$rows=$wpdb->get_col($wpdb->prepare("SELECT b.email FROM $sessions d INNER JOIN $bookings b ON b.session_id=d.id AND b.institute_id=d.institute_id WHERE d.institute_id=%d AND d.lecture_id=%d AND b.booking_status='booked'",$institute_id,$lecture['id']));foreach($rows as $email){if(is_email($email)){$emails[]=strtolower($email);}}}elseif($lecture['student_id']){$email=$wpdb->get_var($wpdb->prepare("SELECT email FROM $students WHERE id=%d AND institute_id=%d",$lecture['student_id'],$institute_id));if(is_email($email)){$emails[]=strtolower($email);}}else{$assign=EduFlow_DB::table('batch_students');$rows=$wpdb->get_col($wpdb->prepare("SELECT s.email FROM $assign a INNER JOIN $students s ON s.id=a.student_id AND s.institute_id=a.institute_id WHERE a.institute_id=%d AND a.batch_id=%d AND a.assignment_status='active'",$institute_id,$lecture['batch_id']));foreach($rows as $email){if(is_email($email)){$emails[]=strtolower($email);}}}$attendees=self::valid_attendees($emails);$start=(new DateTimeImmutable($lecture['start_datetime'],new DateTimeZone('UTC')))->format(DateTimeInterface::RFC3339);$end=(new DateTimeImmutable($lecture['end_datetime'],new DateTimeZone('UTC')))->format(DateTimeInterface::RFC3339);return array('summary'=>'EduFlow: '.($batch['batch_name']??$lecture['canonical_id']),'description'=>'EduFlow Lecture '.$lecture['canonical_id'],'start'=>array('dateTime'=>$start,'timeZone'=>'UTC'),'end'=>array('dateTime'=>$end,'timeZone'=>'UTC'),'attendees'=>$attendees,'extendedProperties'=>array('private'=>array('eduflow_lecture_id'=>$lecture['canonical_id'],'eduflow_institute_id'=>(string)$institute_id)),'conferenceData'=>array('createRequest'=>array('requestId'=>self::conference_request_id($institute_id,$lecture['canonical_id']),'conferenceSolutionKey'=>array('type'=>'hangoutsMeet'))));}
	public static function valid_attendees($emails){$valid=array();foreach((array)$emails as $email){$email=strtolower(sanitize_email((string)$email));if($email&&is_email($email)){$valid[$email]=array('email'=>$email);}}return array_values($valid);}
	public static function conference_request_id($institute_id,$canonical_id){return substr(hash('sha256','eduflow:'.absint($institute_id).':'.sanitize_text_field($canonical_id)),0,64);}
	private static function meet_url($event){foreach(($event['conferenceData']['entryPoints']??array()) as $point){if('video'===($point['entryPointType']??'')&&!empty($point['uri'])){return esc_url_raw($point['uri']);}}return '';}
	private static function request($method,$url,$body,$token,$allow_missing=false){$args=array('method'=>$method,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$token,'Accept'=>'application/json'));if(null!==$body){$args['headers']['Content-Type']='application/json';$args['body']=wp_json_encode($body);}$response=wp_remote_request($url,$args);if(is_wp_error($response)){return new WP_Error('google_transport','Google request temporarily failed.');}$code=wp_remote_retrieve_response_code($response);if($allow_missing&&in_array($code,array(404,410),true)){return array();}$decoded=json_decode(wp_remote_retrieve_body($response),true);if($code<200||$code>=300){$message=sanitize_text_field($decoded['error']['message']??'Google API request failed.');return new WP_Error('google_http_'.$code,$message,array('status'=>$code));}return is_array($decoded)?$decoded:array();}
	private static function json_response($response){if(is_wp_error($response)){return new WP_Error('google_transport','Google request temporarily failed.');}$code=wp_remote_retrieve_response_code($response);$body=json_decode(wp_remote_retrieve_body($response),true);return $code>=200&&$code<300&&is_array($body)?$body:new WP_Error('google_oauth_failed',sanitize_text_field($body['error_description']??'Google OAuth request failed.'));}
	private static function retryable($error){return 'google_transport'===$error->get_error_code()||in_array((int)str_replace('google_http_','',$error->get_error_code()),array(408,429,500,502,503,504),true);}
	private static function fail($map,$error,$retryable){global $wpdb;$message=sanitize_text_field($error->get_error_message());$wpdb->update(EduFlow_DB::table('google_events'),array('sync_status'=>'failed','sync_attempts'=>(int)$map['sync_attempts']+1,'last_error'=>$message,'updated_at'=>current_time('mysql',true)),array('id'=>$map['id'],'institute_id'=>$map['institute_id']));EduFlow_Audit_Service::log('google_sync_failed','class',$map['lecture_id'],null,array('sync_status'=>'failed','error_code'=>$error->get_error_code()),$map['institute_id']);return new WP_Error($retryable?'retryable_google_sync':'permanent_google_sync',($retryable?'[retryable] ':'').$message);}
